from __future__ import annotations
from .canonical import with_digest
def build_provenance(bundle:dict,matrix:dict,evidence:dict,decision:dict)->dict:
    nodes=[{'node_id':'ACL11_HANDOFF','artifact_type':'ACL11_TO_ACL12','artifact_digest':bundle['handoff']['handoff_digest']},{'node_id':'ACL11_CUSTODY_DECISION','artifact_type':'RUNTIME_CUSTODY_DECISION','artifact_digest':bundle['decision']['custody_decision_digest']},{'node_id':'ACL12_CONTROL_MATRIX','artifact_type':'SECURITY_CONTROL_MATRIX','artifact_digest':matrix['assessment_digest']},{'node_id':'ACL12_EVIDENCE_BUNDLE','artifact_type':'SECURITY_EVIDENCE_BUNDLE','artifact_digest':evidence['evidence_bundle_digest']},{'node_id':'ACL12_READINESS_DECISION','artifact_type':'SECURITY_READINESS_DECISION','artifact_digest':decision['readiness_decision_digest']}]
    edges=[{'from':'ACL11_HANDOFF','to':'ACL11_CUSTODY_DECISION'},{'from':'ACL11_CUSTODY_DECISION','to':'ACL12_CONTROL_MATRIX'},{'from':'ACL12_CONTROL_MATRIX','to':'ACL12_EVIDENCE_BUNDLE'},{'from':'ACL12_EVIDENCE_BUNDLE','to':'ACL12_READINESS_DECISION'}]
    return with_digest({'schema_version':'1.0.0','nodes':nodes,'edges':edges,'reaches_acl11_runtime_custody':True,'runtime_candidate_invented':False,'runtime_generation_materialized':False,'production_security_evidence_invented':False,'production_key_material_accessed':False,'live_order_authority_created':False,'capital_authority_created':False},'graph_digest')
